export const KK_SF6_FIXES = Object.freeze([
  Object.freeze({ id: 'SF6-PS-CLEAN-PREFIX', finding: 'run-kk-intraday.mjs 1.1.0: EP and PS walk the same sha256 order, EP first; the PS loop skipped every cached key, so PS days that are also EP candidates were cached up to the EP frontier, all other PS days only up to the PS frontier', before: 'PS evaluated on every cached PS day (run 39939887192: 2 065 days, 65 of them cached by the EP loop, ~14 expected in an unbiased PS prefix: gap-up PS days ~4.5x over-represented)', after: 'PS evaluated on its clean hash prefix only (CLEAN); keys cached only via the EP path beyond it are dropped and counted; BEFORE_FIX is still computed for the comparison' }),
  Object.freeze({ id: 'SF6-EP-COMMON-DAY-SET', finding: 'kk-ep-lifecycle.mjs:113 (1.1.0): a day without IEX baseline is NOT_EXECUTED_NO_IEX_VOLUME_BASELINE under PACE_20 but executable under ALT-NO-VOLUME-RULE', before: 'EP variants on different day sets (run 39939887192: REF 103 days NOT_EXECUTED_NO_IEX_VOLUME_BASELINE, 172 EP days with too few IEX baseline sessions; no EP day was cached via the PS path in that run because the PS prefix was shorter than the EP prefix, but the code allowed it)', after: 'every EP variant on one common day set (EP prefix, minutes and baseline mean > 0); excluded days counted per reason; cached days outside the set are NOT_EVALUATED_OUTSIDE_DAY_SET for every variant' }),
  Object.freeze({ id: 'SF6-PS-OPEN-AT-DATA-END', finding: 'kk-ps-study.mjs:151 / run-kk-intraday.mjs:273-278 (1.1.0): OPEN_AT_DATA_END only in the status counts, never in the metrics', before: 'open shorts (incl. delisted securities) silently left out of every metric', after: 'counted publicly (openAtDataEnd, by terminal cause); sealed metrics closedOnly (unchanged population) and withOpenMarked (marked to the last finite close with exit costs)' }),
  Object.freeze({ id: 'SF6-PS-MEDIAN', finding: 'run-kk-intraday.mjs:278 (1.1.0): medianNetReturn = rs[floor(n / 2)]', before: 'upper median for an even trade count', after: 'proper median (mean of the two middle values); only sealed medians of even-count variants change, nothing pinned' }),
]);
/** Supertrader 6.0 additions (pre-registered before any 6.0 result): reporting variant, strata, cache-only mode. */
export const KK_SF6_ADDITIONS = Object.freeze({
  daySets: Object.freeze(['BEFORE_FIX (1.1.0 behaviour, comparison only)', 'CLEAN (reference)', ...STRATA_SCHEMES.map((x) => `STRAT_${x.id}`)]),
  psOverlap: Object.freeze({ reference: PS_OVERLAP_REFERENCE, reportingVariants: PS_REPORTING_VARIANTS }),
  strata: Object.freeze({ version: KK_SAMPLE_VERSION, schemes: STRATA_SCHEMES, liquidityBoundsUsd: LIQUIDITY_BOUNDS, liquidityBuckets: LIQUIDITY_BUCKETS, minPopulation: STRATA_MIN_POPULATION, registrySha256: kkSampleRegistrySha256(), public: 'per-stratum counts only', sealed: 'per-stratum metrics' }),
  cacheOnly: 'workflow mode kk-intraday-cache: --cache-only, both fetch loops skipped, no API key, 0 requests asserted (mandate: use the existing cache first, no additional requests)',
});

const blockersEp = ['catalyst identity and timestamp (KK-015 / -038 / -039 / -040): DATA_BLOCKED by owner decision (no news database)', 'consolidated intraday volume: only the IEX venue (1-5 %) is available; KK-016 / -037 read on IEX only', 'intraday history before 2017 (IEX starts 2017): candidates 2016 are screened, never simulated', 'minute cache is private and not frozen in the research snapshot: reproducible via its sha256 in the sealed receipt, not certifiable', 'request budget: one run covers a deterministic hash-order sample of the candidate days, not all of them (no mass download)'];
const blockersPs = ['borrow availability, locates and fees (KK-030): DATA_BLOCKED, every short is hypothetical', 'no short book on the shared engine: trade-level study only, no portfolio return', 'consolidated intraday prices and volume: IEX venue only; VWAP is an IEX VWAP', 'intraday history before 2017', 'request budget: PS gets the third of a run budget left after EP, a deterministic hash-order sample of 65 216 days'];

export function buildKkEpPs() {
  const runs = (key) => KK_SNAPSHOT_RUNS.filter((r) => r.strategies?.includes(key));
  // a run over a deterministic hash-order sample of the candidate days is labelled as such until coverage is complete
  const sample = (key) => (runs(key).some((r) => r.coverage?.complete) ? '' : '_HASH_ORDER_SAMPLE');
  const ep = {
    strategyId: KK_EPISODIC_PIVOT.strategyId, candidateId: 'C09', version: KK_EP_LIFECYCLE_VERSION, intraday: KK_INTRADAY_VERSION, label: EP_LABEL,
    contract: { implementationStatus: deriveImplementationStatus(KK_EPISODIC_PIVOT), ruleStatuses: Object.fromEntries(KK_EPISODIC_PIVOT.rules.filter((r) => r.id.startsWith('KK-SF-EP')).map((r) => [r.id, r.status])), measurementClassOfTheOriginalMethod: 'NOT_MEASURABLE (unchanged)' },
    classes: [{ id: EP_CLASS.CHART, layer: 'A_DAILY_SCREEN', assignable: true }, { id: EP_CLASS.INTRADAY_CONFIRMED, layer: 'B_INTRADAY_IEX', assignable: true }, { id: EP_CLASS.ORIGINAL, layer: 'CATALYST', assignable: EP_ORIGINAL_CLASS_ASSIGNABLE, why: 'no verified catalyst data (owner decision 2026-10-23)' }],
    layers: { A_DAILY_SCREEN: 'frozen research snapshot, all history, decided at the official open of the gap day', B_INTRADAY_IEX: 'REAL Tiingo IEX minutes 2017+, decided in time order; no minute derived from a daily bar' },
    researchStage: runs('EP').length ? `CHART_EP_INTRADAY_MODEL_STUDY_IEX_VENUE${sample('EP')}` : 'CHART_EP_IMPLEMENTED_SNAPSHOT_RUN_PENDING',
    engine: 'shared research engine (research-v1), order type INTRADAY_RESOLVED', reference: EP_REFERENCE_CONFIG, variants: EP_RUN_VARIANTS.map((v) => ({ id: v.id, changes: v.changes })), variantRegistrySha256: epVariantRegistrySha256(), modelAssumptions: EP_MODEL_ASSUMPTIONS, blockers: blockersEp, runs: runs('EP'),
    liveReadiness: 'LIVE_NOT_APPROVED', certification: 'DIAGNOSTIC_NOT_CERTIFIED',
  };
  const ps = {
    strategyId: KK_PARABOLIC_SHORT.strategyId, candidateId: 'C10', version: KK_PS_STUDY_VERSION, intraday: KK_INTRADAY_VERSION, label: PS_LABEL,
    contract: { implementationStatus: deriveImplementationStatus(KK_PARABOLIC_SHORT), ruleStatuses: Object.fromEntries(KK_PARABOLIC_SHORT.rules.filter((r) => r.id.startsWith('KK-SF-PS')).map((r) => [r.id, r.status])), measurementClassOfTheOriginalMethod: 'NOT_MEASURABLE (unchanged)' },
    classes: [{ id: PS_CLASS.CHART, layer: 'A_DAILY_SCREEN', assignable: true }, { id: PS_CLASS.INTRADAY_CONFIRMED, layer: 'B_INTRADAY_IEX', assignable: true }, { id: PS_CLASS.EXECUTABLE, layer: 'BORROW', assignable: PS_EXECUTABLE_CLASS_ASSIGNABLE, why: 'no historical borrow / locate / fee data' }],
    layers: { A_DAILY_SCREEN: 'frozen research snapshot, all history, decided at the close before the trade day', B_INTRADAY_IEX: 'REAL Tiingo IEX minutes 2017+, decided in time order; no minute derived from a daily bar' },
    researchStage: runs('PS').length ? `CHART_PS_TRADE_LEVEL_SHORT_MODEL_STUDY_IEX_VENUE${sample('PS')}` : 'CHART_PS_IMPLEMENTED_SNAPSHOT_RUN_PENDING',
    engine: 'trade-level short study (no portfolio, no borrow cost)', costs: PS_COSTS, reference: PS_REFERENCE_CONFIG, variants: PS_RUN_VARIANTS.map((v) => ({ id: v.id, changes: v.changes })), variantRegistrySha256: psVariantRegistrySha256(), modelAssumptions: PS_MODEL_ASSUMPTIONS, blockers: blockersPs, runs: runs('PS'),
    liveReadiness: 'LIVE_NOT_APPROVED', certification: 'DIAGNOSTIC_NOT_CERTIFIED',
  };
  const authoritative = KK_SNAPSHOT_RUNS.filter((r) => r.role === 'AUTHORITATIVE');
  const sf6 = { runner: KK_RUNNER_VERSION, status: authoritative.length ? 'RUN_ON_CURRENT_CODE' : 'CACHE_ONLY_RERUN_PENDING', fixes: KK_SF6_FIXES, additions: KK_SF6_ADDITIONS, samplingAssumptions: KK_SAMPLE_ASSUMPTIONS };
  const statements = {
    certification: 'DIAGNOSTIC_NOT_CERTIFIED: model studies, never a strategy backtest or a performance claim',
    sample: 'deterministic sha256(TICKER|date) prefix of the candidate days, outcome-independent but NOT automatically representative: NOT a representative backtest of all candidates and not to be extrapolated; the Supertrader 6.0 stratified samples equalise the sampling fraction per year x liquidity [x regime] stratum, they remain samples',
    iexVolume: 'IEX venue only (1-5 % of the consolidated volume): compared only with IEX volume, never treated as market volume',
    shorts: 'every PS trade is a hypothetical one-unit short; borrow, locates and fees unknown (KK-030 DATA_BLOCKED): never a historically executable short sale',
    license: 'Tiingo IEX minutes for internal, non-displaying use: private cache and owner-encrypted results only; public outputs carry counts and hashes, never minute values',
  };
  // owner decision E7-6 (2026-10-25): the one pre-registered extension sample, evaluated beside the unchanged references
  const extRun = authoritative.find((r) => r.extE7_6);
  const extensionE7_6 = {
    decision: 'E7-6 (owner, 2026-10-25): einmalig bis zu 550 zusaetzliche Tiingo-Intraday-Anfragen im bestehenden Budget, vorab geschichtet, keine Auswahl nach Profitabilitaet, keine Aenderung bisheriger Referenzen',
    license: 'Tiingo OWNER_DECLARED_LICENSED (quant/config/provider-profiles.json); owner approval 2026-10-01 covers fetching, private storage and internal evaluation in the existing subscription (docs/SUPERTRADER_VALIDATION_INTERNAL.md); contract text not in the repository (gap); minutes stay private, public output counts and hashes only',
    registration: EXT_E7_6_REGISTRATION, registrySha256: kkExtE76RegistrySha256(),
    status: extRun ? 'FETCHED_ONCE_EVALUATED_CACHE_ONLY' : 'PRE_REGISTERED_NOT_FETCHED',
    run: extRun ? extRun.runId : null,
    requests: extRun ? { cap: extRun.extE7_6.requestCap, planned: extRun.extE7_6.runs.count.plan.requests, used: extRun.extE7_6.runs.fetch.requestsUsed, evaluation: extRun.extE7_6.runs.evaluation.requestsThisRun } : null,
    referencesUnchanged: 'CLEAN (reference), BEFORE_FIX and STRAT_* are computed from the reference cache only; every reference block of the evaluation run equals the previous AUTHORITATIVE run',
    statement: 'a larger deterministic hash-order sample, IEX venue only, NOT a strategy backtest and not representative of all candidates; no certification change: EP and PS stay VALIDATION_BLOCKED (catalyst / borrow data, IEX only)',
  };
  return { schema: KK_EP_PS_SCHEMA, statements, ownerDecision: 'chart-first 2026-10-23: no news / catalyst database, no new data provider, IEX minutes of the existing Tiingo access only', probes: KK_INTRADAY_PROBES, candidateCounts: KK_CANDIDATE_COUNTS, supertrader6: sf6, extensionE7_6, strategies: { C09: ep, C10: ps } };
}

export function writeKkEpPs(outDir = path.join(SF, 'artifacts')) {
  const a = buildKkEpPs();
  fs.writeFileSync(path.join(outDir, 'STRATEGY-KK-EP-PS-CHART.json'), JSON.stringify(a, null, 1) + '\n');
  return a;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) { const a = writeKkEpPs(); console.log(`kk ep/ps: C09 ${a.strategies.C09.researchStage}, C10 ${a.strategies.C10.researchStage}`); }
